513	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
514	    @Override
515	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
516	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
517	        if (currentOwner != null) {
518	            Pet currentPet = this.clinicService.findPetById(petId);
519	            if (currentPet != null) {
520	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
521	                currentPet.setName(petFieldsDto.getName());
522	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
523	                this.clinicService.savePet(currentPet);
524	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
